const body = $input.item.json.body || $input.item.json;
const message = body.message || body.edited_message || {};
const fromId = String(message.from?.id || '');
const chatId = message.chat?.id || fromId;
const text = (message.text || '').trim();
const allowedId = String($env.TELEGRAM_ALLOWED_USER_ID || '');

if (!fromId || !allowedId || fromId !== allowedId) {
  return [{
    json: {
      authorized: false,
      chatId,
      text,
      command: 'unauthorized',
      replyText: '⛔ Unauthorized: Telegram User ID not authorized.'
    }
  }];
}

let command = 'unknown';
let draftId = null;

if (text.startsWith('/approve')) {
  command = 'approve';
  const parts = text.split(/\s+/);
  if (parts.length > 1 && parts[1]) {
    draftId = parts[1];
  }
} else if (text.startsWith('/reject')) {
  command = 'reject';
  const parts = text.split(/\s+/);
  if (parts.length > 1 && parts[1]) {
    draftId = parts[1];
  }
} else if (text.startsWith('/generate')) {
  command = 'generate';
}

return [{
  json: {
    authorized: true,
    command,
    draftId,
    chatId,
    rawText: text
  }
}];

const stdout = $input.item.json.stdout || '';
const stderr = $input.item.json.stderr || '';
let result = {};
try {
  result = JSON.parse(stdout);
} catch {
  result = { success: false, error: stderr || stdout || 'Unknown execution error' };
}

const prev = $('Security & Command Parser').first().json;
const chatId = prev.chatId;
let replyText = '';

if (result.success) {
  replyText = `✅ *Post Published Successfully to LinkedIn!*\n\n*Draft ID:* #${result.draftId}\n*Live URL:* ${result.liveUrl}\n*Media URN:* \`${result.imageUrn}\``;
} else {
  const draftId = result.draftId || prev.draftId || 'latest';
  replyText = `❌ *Failed to Publish Draft #${draftId}*\n\n*Error:* ${result.error || 'Publishing failed'}\n\n_The draft has been retained in queue for retry._`;
}

return [{
  json: {
    chatId,
    replyText,
    result
  }
}];

const fs = require('fs');
const filePath = 'data/pending_drafts.json';
const prev = $('Security & Command Parser').first().json;
const draftId = prev.draftId;
const chatId = prev.chatId;
let replyText = '';

try {
  if (fs.existsSync(filePath)) {
    const data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    const drafts = Array.isArray(data) ? data : (data.drafts || []);
    let targetId = draftId;
    if (!targetId && drafts.length > 0) {
      targetId = drafts[drafts.length - 1].id;
    }
    const remaining = drafts.filter(d => String(d.id) !== String(targetId));
    const output = Array.isArray(data) ? remaining : { ...data, drafts: remaining };
    fs.writeFileSync(filePath, JSON.stringify(output, null, 2), 'utf8');
    replyText = `🗑️ *Draft Rejected*\n\nDraft #${targetId || 'latest'} has been removed from the queue.`;
  } else {
    replyText = '⚠️ *No pending drafts found to reject.*';
  }
} catch (err) {
  replyText = `❌ *Error rejecting draft:* ${err.message}`;
}

return [{
  json: {
    chatId,
    replyText
  }
}];

const prev = $('Security & Command Parser').first().json;
const chatId = prev.chatId;

return [{
  json: {
    chatId,
    replyText: '⚡ *Generating New Technical Draft...*\n\nA new post breakdown and visual asset are being created. You will receive a preview shortly.'
  }
}];
